<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get,request,newKey} from '../../../../packages/shared/src/client';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,type Row} from '../../../../packages/shared/src/ui';import type {Operation} from '../../../../packages/shared/src/types';import Status from '../../../../packages/shared/src/Status.vue';
const emit=defineEmits<{saved:[]}>(),task=useTask(),ops=useOperations(),simulated=ref(false),duration=ref(5),file=ref<File>(),key=ref(newKey());
onMounted(async()=>{try{simulated.value=(await get<Row>('/environment')).mode==='SIMULATED';}catch{/* unavailable state remains explicit */}});
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0];key.value=newKey();}
async function upload(){const done=await task.run(async()=>{if(!file.value)return;const form=new FormData();form.set('file',file.value);form.set('duration',String(duration.value));const operation=await request<Operation>('/admin/media-upload',{method:'POST',body:form},key.value);const result=await ops.track('media','登记本地视频',operation,key.value);if(result.status!=='SUCCEEDED'){task.message.value='视频登记处理中，可刷新后在操作记录中继续查询';return false;}task.message.value='视频已持久化';return true;});if(done)emit('saved');}
</script><template><article class="card"><h3>上传视频</h3><Status :error="task.error.value" :busy="task.busy.value" :message="task.message.value"/><template v-if="simulated"><el-alert title="本地模拟存储保存真实文件；时长由测试素材显式提供，不代表云转码已完成。" type="warning" :closable="false"/><div class="toolbar"><input aria-label="选择本地视频" type="file" accept="video/mp4,video/webm" @change="choose"/><label>模拟时长（秒）<el-input-number v-model="duration" :min="1" :max="86400"/></label><el-button @click="upload" :disabled="!file || task.busy.value">上传并登记</el-button></div></template><el-alert v-else title="当前环境未启用本地上传。云视频接入需配置上传凭据及对应播放器。" type="info" :closable="false"/></article></template>
